static void*object(const FactoryProxyProfile&p,const FactoryFieldSpec&s){if(s.proxy>=3||(s.width!=1&&s.width!=2&&s.width!=4)||!p.slots[s.proxy]||!p.call[s.proxy]||!p.cast)return nullptr;void*o=*p.slots[s.proxy];return o?const_cast<void*>(p.cast(p.meta[s.proxy],o)):nullptr;}
bool factory_read(const FactoryProxyProfile&p,FactoryField f,int64_t&out){unsigned n=static_cast<unsigned>(f);if(n>=static_cast<unsigned>(FactoryField::Count))return false;auto s=p.fields[n];void*o=object(p,s);if(!o)return false;int status=-1,flags=0;bool bit=false;uint32_t integer=0;void*args[]={s.boolean?static_cast<void*>(&bit):static_cast<void*>(&integer),nullptr,&status,&flags};p.call[s.proxy](o,1,s.index,args);out=s.boolean?int64_t(bit):s.signedValue?int64_t(static_cast<int32_t>(integer)):int64_t(integer);return true;}
bool factory_write(const FactoryProxyProfile&p,FactoryField f,int64_t value){unsigned n=static_cast<unsigned>(f);if(n>=static_cast<unsigned>(FactoryField::Count))return false;auto s=p.fields[n];if(!s.writable||(s.boolean&&value!=0&&value!=1))return false;if(s.signedValue){if(value<INT32_MIN||value>INT32_MAX)return false;}else{uint64_t max=s.width==1?255:s.width==2?65535:s.width==4?UINT32_MAX:0;if(value<0||static_cast<uint64_t>(value)>max)return false;}void*o=object(p,s);if(!o)return false;int status=-1,flags=0;bool bit=value!=0;uint32_t integer=static_cast<uint32_t>(value);void*args[]={s.boolean?static_cast<void*>(&bit):static_cast<void*>(&integer),nullptr,&status,&flags};p.call[s.proxy](o,2,s.index,args);return true;}
